<script setup lang="ts">
import {ref,computed} from 'vue';import {Head,Link,router,usePage} from '@inertiajs/vue3';
import {Settings2,ShieldCheck,Database,PlugZap,BookOpen,Save,Download,Upload,KeyRound,UserRound} from 'lucide-vue-next';
const props=defineProps<{registrationOpen:boolean}>();const page=usePage();const user=computed(()=>(page.props.auth as {user?:{name:string;email:string}}|undefined)?.user);
const name=ref(user.value?.name||'');const email=ref(user.value?.email||'');const current=ref('');const password=ref('');const confirmPassword=ref('');const file=ref<File|null>(null);const busy=ref(false);
function saveProfile(){busy.value=true;router.patch('/profile',{name:name.value,email:email.value},{onFinish:()=>busy.value=false});}
function savePassword(){busy.value=true;router.put('/profile/password',{current_password:current.value,password:password.value,password_confirmation:confirmPassword.value},{onSuccess:()=>{current.value='';password.value='';confirmPassword.value='';},onFinish:()=>busy.value=false});}
function upload(e:Event){const target=e.target as HTMLInputElement;file.value=target.files?.[0]||null;}
function restore(){if(!file.value||!confirm('¿Importar el respaldo a tu cuenta? Se actualizarán datos coincidentes.'))return;
 const data=new FormData();data.append('backup',file.value);busy.value=true;router.post('/backup/import',data,{forceFormData:true,onFinish:()=>busy.value=false});}
</script>
<template><Head title="Configuración"/><div class="content"><div class="page-head"><div><div class="eyebrow">✦ Preferencias y seguridad</div><h1>Configuración</h1><p class="lead">Tu cuenta, preferencias de lectura y datos.</p></div></div>
<div class="grid grid-2"><section class="panel"><h3><BookOpen :size="20" style="vertical-align:middle;color:var(--accent)"/> Lector</h3><p class="muted">Desde Reader podés elegir el ancho, lectura vertical o individual, crear marcadores y reanudar lecturas.</p><p class="light-note">Ancho y modo se guardan en este navegador; el progreso se guarda por usuario en MySQL.</p><Link href="/history" class="button secondary">Mi historial</Link></section>
<section class="panel"><h3><PlugZap :size="20" style="vertical-align:middle;color:var(--accent)"/> Suwayomi</h3><p class="muted">Configura <code>SUWAYOMI_URL=http://127.0.0.1:4567</code> en tu .env. Encendé el servidor Suwayomi antes de explorar.</p><Link href="/extensions" class="button secondary">Extensiones</Link></section>
<section class="panel"><h3><UserRound :size="20" style="vertical-align:middle;color:var(--accent)"/> Mi perfil</h3><form @submit.prevent="saveProfile"><div class="field"><label>Nombre</label><input v-model="name" required minlength="2" maxlength="80" class="input"/></div><div class="field"><label>Correo</label><input v-model="email" type="email" required class="input"/></div><button class="button primary" :disabled="busy"><Save/> Guardar perfil</button></form></section>
<section class="panel"><h3><KeyRound :size="20" style="vertical-align:middle;color:var(--accent)"/> Cambiar contraseña</h3><form @submit.prevent="savePassword"><div class="field"><label>Contraseña actual</label><input v-model="current" type="password" required class="input"/></div><div class="field"><label>Nueva contraseña (mínimo 10)</label><input v-model="password" type="password" minlength="10" required class="input"/></div><div class="field"><label>Confirmar nueva contraseña</label><input v-model="confirmPassword" type="password" minlength="10" required class="input"/></div><button class="button primary" :disabled="busy"><Save/> Actualizar contraseña</button></form></section>
<section class="panel"><h3><Database :size="20" style="vertical-align:middle;color:var(--accent)"/> Respaldo de tu cuenta</h3><p class="muted">Exportá biblioteca, colecciones, marcadores y progreso en JSON, o importá un respaldo anterior.</p><a class="button secondary" href="/backup/export"><Download/> Exportar JSON</a><div class="divider"/><form @submit.prevent="restore"><div class="field"><label>Seleccionar respaldo (.json)</label><input type="file" accept=".json,application/json" class="input" @change="upload"/></div><button class="button primary" :disabled="busy||!file"><Upload/> Importar respaldo</button></form><p class="light-note">No incluye imágenes descargadas ni contraseñas. Guardá tu respaldo en un lugar privado.</p></section>
<section class="panel"><h3><ShieldCheck :size="20" style="vertical-align:middle;color:var(--accent)"/> Seguridad</h3><p class="muted">Registro: <span class="pill">{{registrationOpen?'Abierto':'Cerrado'}}</span></p><p class="light-note">Tras crear tu cuenta, configurá <code>ALLOW_REGISTRATION=false</code> y <code>APP_DEBUG=false</code>. Para publicar el sitio usá HTTPS y un túnel privado. No expongás Suwayomi directamente.</p></section></div><div class="notice">MangaWeb no distribuye títulos ni extensiones de terceros; los obtiene mediante el servidor Suwayomi configurado por vos.</div>
</div></template>
